    /**
     * Get a translated string (PHP server-side).
     * Falls back to default if no custom translation set.
     */
    public static function get( $key, ...$args ) {
        $lang     = get_option( 'bt_site_lang', 'en' );
        $custom   = get_option( 'bt_strings_' . $lang, array() );
        $defaults = self::get_default_strings();

        $string = isset( $custom[ $key ] ) ? $custom[ $key ] : ( isset( $defaults[ $key ] ) ? $defaults[ $key ] : $key );

        if ( ! empty( $args ) ) {
            $string = vsprintf( $string, $args );
        }

        return $string;
    }

    /**
     * Echo a translated string.
     */
    public static function e( $key, ...$args ) {
        echo self::get( $key, ...$args );
    }

    /**
     * Return escaped HTML string.
     */
    public static function esc( $key, ...$args ) {
        return esc_html( wp_strip_all_tags( self::get( $key, ...$args ) ) );
    }

    /**
     * Wrap text in a data-i18n span for JS translation.
     */
    public static function span( $key, $tag = 'span' ) {
        $default = self::get( $key );
        return '<' . esc_attr($tag) . ' data-i18n="' . esc_attr($key) . '">' . $default . '</' . esc_attr($tag) . '>';
    }

    public static function init() {
        // Inject JS translation dictionary into wp_head
        add_action( 'wp_head', array( __CLASS__, 'inject_js_strings' ), 5 );
    }

    /**
     * Inject all translation strings as a JS object for client-side i18n.
     * Languages stored in bt_translations WP option.
     */
    public static function inject_js_strings() {
        $translations = get_option( 'bt_translations', self::get_default_translations() );
        echo '<script id="bt-i18n-data">window.BT_STRINGS=' . wp_json_encode( $translations['strings'] ) . ';window.BT_LANGS=' . wp_json_encode( $translations['langs'] ) . ';</script>' . "\n";
    }

