    /**
     * Admin page for managing translations.
     */
    public static function render_admin_page() {
        if ( ! current_user_can( 'manage_options' ) ) wp_die( 'Unauthorized' );

        if ( isset( $_POST['bt_save_strings'] ) && check_admin_referer( 'bt_i18n', 'bt_i18n_nonce' ) ) {
            $lang    = sanitize_text_field( $_POST['bt_edit_lang'] ?? 'en' );
            $strings = array();
            foreach ( $_POST['bt_string'] ?? array() as $key => $val ) {
                $strings[ sanitize_key( $key ) ] = wp_kses_post( $val );
            }
            update_option( 'bt_strings_' . $lang, $strings );

            // Rebuild JS translations cache
            $translations = self::get_default_translations();
            foreach ( $translations['strings'] as $key => &$langs ) {
                $custom = get_option( 'bt_strings_en', array() );
                if ( isset( $custom[$key] ) ) $langs['en'] = $custom[$key];
            }
            update_option( 'bt_translations', $translations );

            echo '<div class="notice notice-success"><p>✅ Strings saved for language: <strong>' . esc_html(strtoupper($lang)) . '</strong></p></div>';
        }

        $defaults = self::get_default_strings();
        $edit_lang = sanitize_text_field( $_GET['lang'] ?? 'en' );
        $custom    = get_option( 'bt_strings_' . $edit_lang, array() );
        $translations = self::get_default_translations();
        $langs = $translations['langs'];
        
?>
        <div class="wrap" style="max-width:1100px">
            <h1 style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
                🌐 Translation Manager
            </h1>
            <p style="color:var(--bt-text-3);margin-bottom:20px">
                Edit all user-facing text strings and manage translations for <?php echo count($langs); ?> languages.
                All strings use <code>get_option()</code> — zero hardcoding.
            </p>

            <!-- Language tabs -->
            <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:24px">
                <?php foreach ($langs as $l):
                    $active = ($l['code'] === $edit_lang);
                    $url = admin_url('admin.php?page=bt-i18n&lang=' . $l['code']);
                ?>
                <a href="<?php echo esc_url($url); ?>" style="display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border-radius:20px;font-size:13px;font-weight:600;text-decoration:none;background:<?php echo $active?'rgba(0,255,102,.15)':'rgba(255,255,255,.04)';?>;border:1px solid <?php echo $active?'rgba(0,255,102,.4)':'rgba(255,255,255,.08)';?>;color:<?php echo $active?'var(--bt-accent)':'var(--bt-text-3)';?>">
                    <?php echo $l['flag']; ?> <?php echo esc_html($l['name']); ?>
                    <?php $cust = get_option('bt_strings_'.$l['code'], array()); if (!empty($cust)) echo '<span style="font-size:10px;background:rgba(0,255,102,.2);color:var(--bt-accent);border-radius:3px;padding:1px 5px">'.count($cust).' custom</span>'; ?>
                </a>
                <?php endforeach; ?>
            </div>

            <form method="post">
                <?php wp_nonce_field('bt_i18n','bt_i18n_nonce'); ?>
                <input type="hidden" name="bt_edit_lang" value="<?php echo esc_attr($edit_lang); ?>">
                <input type="hidden" name="bt_save_strings" value="1">

                <div style="background:var(--bt-bg-elev);border:1px solid rgba(255,255,255,.08);border-radius:0;overflow:hidden;margin-bottom:20px">
                    <div style="padding:14px 18px;border-bottom:1px solid rgba(255,255,255,.06);display:grid;grid-template-columns:200px 1fr 1fr;gap:12px">
                        <div style="font-size:11px;font-weight:700;color:var(--bt-text-3);text-transform:uppercase;letter-spacing:.5px">Key</div>
                        <div style="font-size:11px;font-weight:700;color:var(--bt-text-3);text-transform:uppercase;letter-spacing:.5px">English (default)</div>
                        <div style="font-size:11px;font-weight:700;color:var(--bt-accent);text-transform:uppercase;letter-spacing:.5px"><?php echo esc_html(strtoupper($edit_lang)); ?> Translation</div>
                    </div>
                    <?php foreach ($defaults as $key => $default_val):
                        $current = isset($custom[$key]) ? $custom[$key] : '';
                        $is_long = strlen($default_val) > 80;
                    ?>
                    <div style="padding:10px 18px;border-bottom:1px solid rgba(255,255,255,.03);display:grid;grid-template-columns:200px 1fr 1fr;gap:12px;align-items:start">
                        <code style="font-size:11px;color:var(--bt-text-3);word-break:break-all;padding-top:6px"><?php echo esc_html($key); ?></code>
                        <div style="font-size:12px;color:var(--bt-text-4);padding-top:6px;line-height:1.5"><?php echo esc_html(wp_strip_all_tags($default_val)); ?></div>
                        <?php if ($is_long): ?>
                        <textarea name="bt_string[<?php echo esc_attr($key); ?>]" rows="2"
                            placeholder="<?php echo esc_attr(wp_strip_all_tags($default_val)); ?>"
                            style="width:100%;background:#0A0B0D;border:1px solid rgba(255,255,255,.1);color:var(--bt-text);border-radius:0;padding:6px 10px;font-size:12px;font-family:inherit;outline:none;resize:vertical"><?php echo esc_textarea($current); ?></textarea>
                        <?php else: ?>
                        <input type="text" name="bt_string[<?php echo esc_attr($key); ?>]"
                            value="<?php echo esc_attr($current); ?>"
                            placeholder="<?php echo esc_attr(wp_strip_all_tags($default_val)); ?>"
                            style="width:100%;background:#0A0B0D;border:1px solid rgba(255,255,255,.1);color:var(--bt-text);border-radius:0;padding:6px 10px;font-size:12px;font-family:inherit;outline:none">
                        <?php endif; ?>
                    </div>
                    <?php endforeach; ?>
                </div>
                <button type="submit" style="background:linear-gradient(135deg,var(--bt-accent),var(--bt-accent));color:#0A0B0D;font-weight:700;padding:12px 28px;border:none;border-radius:0;cursor:pointer;font-size:14px;font-family:inherit">
                    💾 Save <?php echo esc_html(strtoupper($edit_lang)); ?> Translations
                </button>
                <?php if ($edit_lang !== 'en'): ?>
                <a href="<?php echo esc_url(admin_url('admin.php?page=bt-i18n&lang=en')); ?>" style="margin-left:12px;color:var(--bt-accent);font-size:13px">Edit English defaults →</a>
                <?php endif; ?>
            </form>
        </div>
        <?php
    }
}

/**
 * Global helper function — use __bt('key') anywhere in templates.
 */
function __bt( $key, ...$args ) {
    return BT_I18N::get( $key, ...$args );
}
function _ebt( $key, ...$args ) {
    echo BT_I18N::get( $key, ...$args );
}
